#ifndef ABOUT_FONT_H
#define ABOUT_FONT_H
/* Antialiased About glyphs for ASCII 32..126, generated by
   tools/make-about-font.py. Coverage rows are width bytes per row for the
   full line height; y = 0 is the top of the line. */
enum { ABOUT_TITLE, ABOUT_BODY, ABOUT_SMALL, ABOUT_NAME, ABOUT_STYLES };
enum { ABOUT_FIRST_CHAR = 32, ABOUT_LAST_CHAR = 126 };
typedef struct { short bearing, width, advance; unsigned short offset; } AboutGlyph;
typedef struct {
    unsigned char height, baseline;
    const AboutGlyph *glyphs;
    const unsigned char *coverage;
} AboutFace;
extern const AboutFace about_font[ABOUT_STYLES];
#endif
